-- Source: reference/Final Fantasy Sound Sources (Detailed) - Ivalice Alliance.csv
-- Section 5: Final Fantasy Tactics A2: Grimoire of the Rift (CSV rows 349-514).
-- Most thoroughly sourced game in the Ivalice file. 151 sample rows across 8 tracks
-- (4, 5, 8, 22, 27, 33, 35, 38). Track 35 is flagged "(Unused)" so its rows are
-- category 'unused'. "(OST Version only)" sub-headers switch following rows to
-- category 'bonus'.
-- Sonic Implants ships both "Symphonic Strings Collection" (plural) and "Symphonic
-- String Collection" (singular) in this CSV — preserved verbatim as distinct
-- products per the FF Detailed contributor-drift convention; cleanup deferred.
-- EastWest trailing-space source variants ("EastWest - Symphonic Orchestra ") are
-- normalized via internal-whitespace rule in the batch plan.

INSERT OR IGNORE INTO manufacturers (name) VALUES
  ('Sonic Implants');

INSERT OR IGNORE INTO products (manufacturer_id, name, type) VALUES
  ((SELECT id FROM manufacturers WHERE name = 'Sonic Implants' COLLATE NOCASE), 'Symphonic Strings Collection',  'Sample Library'),
