  ((SELECT id FROM manufacturers WHERE name = 'ProjectSAM'     COLLATE NOCASE), 'SAM Trombone',                  'Sample Library'),
  ((SELECT id FROM manufacturers WHERE name = 'EastWest'       COLLATE NOCASE), 'Voices of the Apocalypse',      'Sample Library');

